use axum::{Router, http::StatusCode, routing::get};

use crate::{
    domain::services::{entity_details::EntityDetailsService, entity_search::EntitySearchService},
    inbound::http::{handlers, state::AppState},
};

/// Routes for the exposed application
pub fn routes<E: EntitySearchService, D: EntityDetailsService>() -> Router<AppState<E, D>> {
    let router = Router::new()
        .route("/healthz", get(|| async { StatusCode::NO_CONTENT }))
        .route("/search", get(handlers::search_entities))
        .route("/members/{id}", get(handlers::member_details))
        .route("/funders/{id}", get(handlers::funder_details));
    super::tracing::instrument(router)
}
use anyhow::Context;
use std::sync::Arc;

use tokio::net::TcpListener;

use crate::{
    domain::services::entity_search::Service as EntitySearchService,
    inbound::http::{config::ServerConfig, routes::routes, state::AppState},
    outbound::ExposedDatabase,
};

/// Subscriber installation failed before server startup could use tracing.
#[derive(Debug, thiserror::Error)]
pub enum SubscriberInitializationError {
    /// `RUST_LOG` contains a non-Unicode value.
    #[error("server tracing initialization failed: invalid RUST_LOG")]
    Environment(#[from] std::env::VarError),
    /// `RUST_LOG` contains invalid filter directives.
    #[error("server tracing initialization failed: invalid filter")]
    Filter(#[from] tracing_subscriber::filter::ParseError),
    /// A process-wide subscriber could not be installed.
    #[error("server tracing initialization failed: subscriber installation failed")]
    Install(#[from] tracing_subscriber::util::TryInitError),
}

/// Loads server configuration and serves HTTP on port 6999.
///
/// Initializes a process-wide subscriber after loading dotenv. Embedded hosts
/// with their own subscriber should call [`serve_exposed`] instead.
///
/// # Errors
/// Returns an error if subscriber setup, configuration, runtime creation, or
/// server startup fails.
pub fn run_server() -> anyhow::Result<()> {
    dotenvy::dotenv().ok();
    super::tracing::init_subscriber()?;
    let config = ServerConfig::from_env().context("reading HTTP server configuration")?;

    tokio::runtime::Runtime::new()
        .context("creating HTTP server runtime")?
        .block_on(async {
            let listener = TcpListener::bind("0.0.0.0:6999")
                .await
                .context("binding HTTP server port 6999")?;
            serve_exposed(&config, listener).await
        })
}

/// Starts an `exposed` HTTP server
///
/// # Errors
/// Returns an error if connecting to the database or serving HTTP fails.
pub async fn serve_exposed(config: &ServerConfig, listener: TcpListener) -> anyhow::Result<()> {
    let db = ExposedDatabase::new(&config.connection_string)
        .await
        .context("connecting HTTP server database")?;
    let service = EntitySearchService::new(db.clone(), db.clone());

    let state = AppState {
        entity_search_service: Arc::new(service),
        entity_details_service: Arc::new(crate::domain::services::entity_details::Service::new(db)),
    };
    let router = routes().with_state(state);

    tracing::info!(address = %listener.local_addr()?, "HTTP server listening");
    axum::serve(listener, router)
        .await
        .context("serving HTTP requests")?;

    Ok(())
}
use std::time::{Duration, Instant};

use axum::{
    Router,
    extract::{MatchedPath, Request},
    middleware::{self, Next},
    response::Response,
};
use tracing::{Instrument, Level};
use tracing_subscriber::{EnvFilter, util::SubscriberInitExt};

pub(super) fn init_subscriber() -> Result<(), super::server::SubscriberInitializationError> {
    let directives = match std::env::var("RUST_LOG") {
        Ok(value) => value,
        Err(std::env::VarError::NotPresent) => "warn,exposed=info".into(),
        Err(error) => return Err(error.into()),
    };
    let filter = EnvFilter::builder().with_regex(false).parse(directives)?;
    tracing_subscriber::fmt()
        .json()
        .with_env_filter(filter)
        .with_writer(std::io::stderr)
        .finish()
        .try_init()?;
    Ok(())
}

pub(super) fn instrument<S>(router: Router<S>) -> Router<S>
where
    S: Clone + Send + Sync + 'static,
{
    router.layer(middleware::from_fn(trace_request))
}

async fn trace_request(request: Request, next: Next) -> Response {
    let method = request.method().clone();
    let route = request.extensions().get::<MatchedPath>().cloned();
    let health = route
        .as_ref()
        .is_some_and(|path| path.as_str() == "/healthz");
    let route_name = route.as_ref().map(MatchedPath::as_str);
    let span = if health {
        tracing::span!(Level::DEBUG, "http.request",
            http.request.method = %method, http.route = route_name)
    } else {
        tracing::span!(Level::INFO, "http.request",
            http.request.method = %method, http.route = route_name)
    };
    async move {
        let started = Instant::now();
        let response = next.run(request).await;
        complete(
            &response,
            started.elapsed(),
            &method,
            route.as_ref(),
            health,
        );
        response
    }
    .instrument(span)
    .await
}

fn complete(
    response: &Response,
    latency: Duration,
    method: &axum::http::Method,
    route: Option<&MatchedPath>,
    health: bool,
) {
    let status = response.status();
    let category = if status.is_server_error() {
        Some("http.server_error")
    } else if status.is_client_error() {
        Some("http.client_error")
    } else {
        None
    };
    let route = route.map(MatchedPath::as_str);
    macro_rules! emit {
        ($level:ident) => {
            tracing::$level!(
                name: "http.request.completed",
                name = "http.request.completed",
                http.request.method = %method,
                http.route = route,
                http.response.status_code = u64::from(status.as_u16()),
                duration_ms = latency.as_secs_f64() * 1000.0,
                error.type = category,
            )
        };
    }
    if status.is_server_error() {
        emit!(error);
    } else if status.is_client_error() {
        emit!(warn);
    } else if health {
        emit!(debug);
    } else {
        emit!(info);
    }
}

